from fastapi import FastAPI
from pydantic import BaseModel

app = FastAPI()
bookmarks = {}


class BookmarkIn(BaseModel):
    url: str
    title: str


class BookmarkOut(BaseModel):
    id: int
    url: str
    title: str


@app.post("/bookmarks", response_model=BookmarkOut, status_code=201)
def create_bookmark(bookmark: BookmarkIn):
    new_id = len(bookmarks) + 1
    record = {"id": new_id, "url": bookmark.url, "title": bookmark.title}
    bookmarks[new_id] = record
    return record


@app.get("/bookmarks/{bid}", response_model=BookmarkOut)
def get_bookmark(bid: int):
    return bookmarks[bid]

